-- ============================================================================
-- SIS (SINBA) — Semilla del catálogo de 104 variables de SIS-06-P.
--
-- Extraído y verificado programáticamente cruzando SINBA-VER_26_2026.xlsx
-- (hoja SINBA-SIS-06-P, filas 11-121: biológico + grupo poblacional + dosis)
-- contra SIS-SS-CE-H-2026 (donde viven las claves oficiales SIS, en dos
-- bloques de columnas -- cada fórmula de esa hoja apunta a una fila
-- específica de SIS-06-P, así que el cruce fue exacto, no por texto).
-- 94 de las 104 filas tienen clave oficial; las 10 restantes (sueros,
-- faboterápicos, antitoxinas, "otros biológicos") no alimentan ese reporte.
--
-- Requiere haber corrido sis_schema.sql antes.
-- ============================================================================

on conflict (fila_excel) do update set
  biologico = excluded.biologico, grupo_poblacional = excluded.grupo_poblacional, dosis = excluded.dosis,
  clave_general = excluded.clave_general, clave_afro = excluded.clave_afro, clave_indigena = excluded.clave_indigena,
  clave_migrante = excluded.clave_migrante, orden = excluded.orden;
